/* @author MILO-GAO(高振銘)@2020 */ package page2020.unit;import page2020.View;import page2020.view.B4;import page2020.view.C3;import page2020.view.H5;import page2020.view.bs4.B4button.BtnColor;import page2020.view.bs4.B4button.Outline;import page2020.view.bs4.B4color.Color;import page2020.view.bs4.B4show.D;import page2020.view.bs4.B4element;import page2020.view.bs4.B4image;import page2020.view.bs4.B4table.TableBgHex;import page2020.view.bs4.B4text.TextX;import page2020.view.html5.H5button;public class Upaging extends B4element {	private static final String theader_color = "#17a2b8";	private static final String data_paging = "paging";	private static final String data_member = "member";	private static final String table = "table." + PageKey.paging;	private static final String theader = table + ">thead>tr";	private static final String tbody = table + ">tbody>tr";	public Upaging() {		super();	}	public Upaging(String name, int number, View view) {		super();		super.name(name).cssClass(D.none)			.data(PageKey.type, "upaging")			.data(data_paging, number);		view.selector(theader, 			C3.color(theader_color),			C3.text.lineHeight("2rem"),			C3.text.vertical("text-bottom"),			C3.border.border("bottom", "2px solid " + TableBgHex.info)		);		view.selector(tbody,			C3.text.lineHeight("2rem"),			C3.text.vertical("text-bottom"),			C3.border.border("bottom", "1px solid rgba(0,0,0,0.1)")		);		super.cssClass(D.none, TextX.right, "my-2");		super.append(			this.button("zero", "0").text("0").removeClass(Outline.info).cssClass(BtnColor.info).disabled(true),			this.button("number", "1").text("1"),			this.button("number", "2").text("2"),			this.button("number", "3").text("3"),			this.button("number", "4").text("4"),			this.button("number", "5").text("5"),			this.button("number", "6").text("6"),			this.button("number", "7").text("7"),			this.button("number", "8").text("8"),			this.button("number", "9").text("9"),			this.button("arrow", "previous").icon("chevron-left"),			this.button("control", "first").text("1"),			H5.span().icon("ellipsis-h").cssClass(Color.info),			this.button("control", "1"),			this.button("control", "2"),			this.button("control", "3"),			this.button("control", "4"),			this.button("control", "5"),			H5.span().icon("ellipsis-h").cssClass(Color.info),			this.button("control", "last").text("100"),			this.button("arrow", "next").icon("chevron-right")		);	}	private H5button button(String type, String member) {		return B4.button()			.css(C3.font.family("arial"), C3.width("2rem"), C3.height("2rem"), C3.padding("0"))			.cssClass(Outline.info, B4image.circle)			.data(PageKey.type, type)			.data(data_member, member);	}	@Override	public Upaging copy() {		return (Upaging) super.copy();	}	}